414	function renderCensus(census: RefusalCensus, written: string | null): string {
415		const lines = [
416			`refusal census: ${String(census.summary.sites)} site(s) over ${String(census.filesScanned)} scanned file(s)`,
417			`adapter freeze composite: ${census.adapterFreezeComposite}`,
418			'',
419			'by origin',
420		];
421		for (const key of Object.keys(census.summary.byOrigin))
422			lines.push(`  ${key}: ${String(census.summary.byOrigin[key] ?? 0)}`);
423		lines.push('');
424		lines.push('by classification');
425		for (const key of Object.keys(census.summary.byClassification))
426			lines.push(`  ${key}: ${String(census.summary.byClassification[key] ?? 0)}`);
427		lines.push('');
428		lines.push('by stage');
429		for (const key of Object.keys(census.summary.byStage))
430			lines.push(`  ${key}: ${String(census.summary.byStage[key] ?? 0)}`);
431		lines.push('');
432		lines.push(written === null ? 'written: nothing (verify only)' : `written: ${written}`);
433		lines.push('');
434		for (const line of census.notEstablished) lines.push(`not established: ${line}`);
435		return `${lines.join('\n')}\n`;
436	}
437	
438	function renderVerification(verification: OperatorVerification): string {
439		const lines = [`result: ${verification.result}`, ''];
440		for (const check of verification.checks)
441			lines.push(`  [${check.state}] ${check.name}: ${check.detail}`);
442		lines.push('');
443		for (const line of verification.notEstablished) lines.push(`not established: ${line}`);
444		return `${lines.join('\n')}\n`;
445	}
446	
447	export type OperatorOutcome = Readonly<{
448		text: string;
449		json: unknown;
450		exitCode: number;
451	}>;
452	
453	/**
454	 * Which lane composition a tree gets, if any.
455	 *
456	 * Only the create-react-app lineage gets a generated build configuration,
457	 * because that is the lineage whose lane otherwise carries the origin
458	 * toolchain's declaration and no configuration at all. Every other tree is
459	 * reported as not composed, with the reason, rather than silently receiving
460	 * nothing.
461	 */
462	async function composeLane(
463		appRoot: string,
464		out: string,
465		lineage: string,
466		builder: string,
467	): Promise<LaneComposition> {
468		if (lineage === 'react' && builder === 'react-scripts')
469			return composeReactLane({ appRoot, laneDir: out });
470		if (lineage === 'react')
471			return laneNotComposed(
472				lineage,
473				`this tree declares the builder ${builder} rather than react-scripts, so the Vite-origin adapter reads the application's own configuration at plan time. The lane keeps that configuration rather than having this flow generate a second one.`,
474			);
475		if (lineage === 'angular')
476			return laneNotComposed(
477				lineage,
478				"the generated lane build configuration is the create-react-app composition. The Angular changeset rewrites the workspace's own build declarations through the frozen adapter, so this flow composes no additional configuration for it.",
479			);
480		return laneNotComposed(
481			lineage,
482			`no lane build configuration is published for the ${lineage} lineage.`,
483		);
484	}
485	
486	async function writeRecord(file: string | undefined, value: unknown): Promise<void> {
487		if (file === undefined) return;
488		await mkdir(path.dirname(path.resolve(file)), { recursive: true });
489		await writeFile(path.resolve(file), `${JSON.stringify(value, null, '\t')}\n`);
490	}
491	
492	/**
493	 * Run one operator command and return what it would print.
494	 *
495	 * A named refusal is a returned outcome carrying exit 2, not a thrown stack
496	 * trace: a fleet report has to be able to tally the reason an application was
497	 * declined, and an exception with a formatted stack is not a tally. A defect
498	 * still throws — an exception is the honest shape for something that broke —
499	 * and the caller scores it 1.
500	 */
501	export async function runOperatorCommand(
502		command: OperatorCommand,
503		args: readonly string[],
504	): Promise<OperatorOutcome> {
505		try {
506			return await runOperatorFlow(command, args);
507		} catch (error) {
508			const refusal = pipelineRefusalOf(error);
509			if (refusal === null) throw error;
510			const json = refusalRecord(command, refusal);
511			/**
512			 * Read without the parser, because the parser is itself one of the
513			 * stages that can refuse. A refused run still writes its record: the
514			 * refusal is the outcome the fleet report needs, not the absence of one.
515			 */
516			const recordIndex = args.indexOf('--record');
517			await writeRecord(recordIndex < 0 ? undefined : args[recordIndex + 1], json);
518			return Object.freeze({
519				text: args.includes('--json') ? `${JSON.stringify(json)}\n` : renderRefusal(refusal),
520				json,
521				exitCode: EXIT_REFUSAL,
522			});
523		}
524	}
525	
526	async function runOperatorFlow(
527		command: OperatorCommand,
528		args: readonly string[],
529	): Promise<OperatorOutcome> {
530		const parsed = parseOperatorArguments(command, args);
531		if (parsed.help)
532			return Object.freeze({ text: operatorHelp(command), json: { help: command }, exitCode: 0 });
533		const root = parsed.positional[0] ?? '.';
534		const angular = {
535			sourceDirectories: parsed.flags['--source-dir'],
536			templateDirectories: parsed.flags['--template-dir'],
537			styleSheetDirectories: parsed.flags['--style-dir'],
538		};
539		const react = { entryModule: parsed.flags['--entry']?.[0] };
540		if (command === 'analyze') {
541			const analysis = await analyzeApplication(root);
542			const json = { flow: 'analyze', application: displayPath(root), ...analysis };
543			await writeRecord(parsed.flags['--record']?.[0], json);
544			return Object.freeze({
545				text: parsed.json ? `${JSON.stringify(json)}\n` : renderAnalysis(root, analysis),
546				json,
547				exitCode: 0,
548			});
549		}
550		if (command === 'plan') {
551			const { analysis, plan } = await planApplication({ appRoot: root, angular, react });
552			const json = {
553				flow: 'plan',
554				application: displayPath(root),
555				detected: analysis,
556				plan: { ...plan, files: plan.files.map(({ source: _source, ...rest }) => rest) },
557			};
558			await writeRecord(parsed.flags['--record']?.[0], json);
559			return Object.freeze({
560				text: parsed.json ? `${JSON.stringify(json)}\n` : renderPlan(root, plan),
561				json,
562				exitCode: 0,
563			});
564		}
565		if (command === 'migrate') {
566			const out = parsed.flags['--out']?.[0] as string;
567			const { analysis, plan } = await planApplication({ appRoot: root, angular, react });
568			const applied = await applyPlan(plan, {
569				appRoot: root,
570				out,
571				materialize: parsed.flags['--materialize'] !== undefined,
572			});
573			const composition = await composeLane(root, out, plan.lineage, analysis.builder);
574			await writeLaneFiles(out, composition);
575			const policy: InstallPolicy = Object.freeze({
576				allowRemoteTarballs: parsed.flags['--allow-remote-tarballs'] !== undefined,
577				allowInstallScripts: parsed.flags['--allow-install-scripts'] !== undefined,
578				skipInstallScripts: parsed.flags['--skip-install-scripts'] !== undefined,
579				allowPeerConflicts: parsed.flags['--allow-peer-conflicts'] !== undefined,
580			});
581			const install =
582				parsed.flags['--install'] === undefined
583					? installNotRequested(
584							'--install was not declared. The lane was composed and not installed, and this run establishes nothing about whether its closure resolves.',
585						)
586					: await runLaneInstall(
587							out,
588							policy,
589							process.env,
590							composition.composed ? 'resolve' : 'replay',
591						);
592			const build =
593				parsed.flags['--build'] === undefined
594					? buildNotRequested(
595							'--build was not declared. The lane was composed and not built, and this run establishes nothing about whether it compiles or emits.',
596						)
597					: await runLaneBuild(out);
598			const json = {
599				flow: 'migrate',
600				outcome: 'proceeded',
601				exitCode: EXIT_PROCEEDED,
602				application: displayPath(root),
603				lane: displayPath(out),
604				engine: plan.engine,
605				cell: plan.cell,
606				applied,
607				/**
608				 * The generated sources are not carried in the record. They are in
609				 * the lane, they are digested here, and the specifier the generated
610				 * configuration resolves the frozen adapter by is a path on this
611				 * host — a record is evidence and evidence carries no host paths.
612				 */
613				laneComposition: {
614					...composition,
615					files: composition.files.map(({ source: _source, ...rest }) => rest),
616				},
617				install,
618				build,
619				unhandled: Object.freeze([...plan.unhandled, ...composition.unhandled]),
620				unhandledByStage: Object.freeze({
621					plan: plan.unhandled,
622					lane: composition.unhandled,
623				}),
624				declaredDifferences: Object.freeze([
625					...plan.declaredDifferences,
626					...composition.declaredDifferences,
627				]),
628			};
629			await writeRecord(parsed.flags['--record']?.[0], json);
630			return Object.freeze({
631				text: parsed.json
632					? `${JSON.stringify(json)}\n`
633					: renderApplied(out, applied, composition, install, build),
634				json,
635				exitCode: EXIT_PROCEEDED,
636			});
637		}
638		if (command === 'refusal-census') {
639			const census = await buildRefusalCensus();
640			const target = parsed.flags['--out']?.[0] ?? REFUSAL_CENSUS_FILE;
641			const verifyOnly = parsed.flags['--verify-only'] !== undefined;
642			const derived = `${JSON.stringify(census, null, '\t')}\n`;
643			const published = (await fileExists(path.resolve(target)))
644				? await readFile(path.resolve(target), 'utf8')
645				: null;
646			const matches = published === derived;
647			if (!verifyOnly) await writeRefusalCensus(census, target);
648			const json = {
649				flow: 'refusal-census',
650				file: target,
651				verifyOnly,
652				matchesPublished: matches,
653				published: published !== null,
654				census,
655			};
656			await writeRecord(parsed.flags['--record']?.[0], json);
657			return Object.freeze({
658				text: parsed.json
659					? `${JSON.stringify(json)}\n`
660					: renderCensus(census, verifyOnly ? null : target),
661				json,
662				exitCode: verifyOnly && !matches ? 1 : EXIT_PROCEEDED,
663			});
664		}
665		if (command === 'verify') {
666			const verification = await runOperatorVerification({
667				receipts: parsed.flags['--receipt'],
668				trustDir: parsed.flags['--trust-dir']?.[0],
669			});
670			const json = { flow: 'verify', ...verification };
671			await writeRecord(parsed.flags['--record']?.[0], json);
672			return Object.freeze({
673				text: parsed.json ? `${JSON.stringify(json)}\n` : renderVerification(verification),
674				json,
675				exitCode: verification.result === 'pass' ? 0 : 1,
676			});
677		}
678		const reading = await readSupportedMatrix({ trustDir: parsed.flags['--trust-dir']?.[0] });
679		const rendered = renderSupportedMatrix(reading);
680		const json = {
681			flow: 'supported-matrix',
682			source: reading.source,
683			trustDigest: reading.trustDigest,
684			certification: reading.certification,
685			supportMatrix: reading.matrix,
686		};
687		await writeRecord(parsed.flags['--record']?.[0], json);
688		return Object.freeze({
689			text: parsed.json ? `${JSON.stringify(json)}\n` : rendered,
690			json,
691			exitCode: 0,
692		});
693	}
694

