57	function download(url: string, destination: string): Promise<void> {
58		return new Promise((resolve, reject) => {
59			const request = https.get(url, (response) => {
60				if (
61					(response.statusCode ?? 0) >= 300 &&
62					(response.statusCode ?? 0) < 400 &&
63					response.headers.location
64				) {
65					response.resume();
66					download(response.headers.location, destination).then(resolve, reject);
67					return;
68				}
69				if (response.statusCode !== 200) {
70					response.resume();
71					reject(new Error(`Download failed (${response.statusCode}): ${url}`));
72					return;
73				}
74				const output = createWriteStream(destination, { flags: 'wx' });
75				response.pipe(output);
76				output.once('finish', () => output.close(() => resolve()));
77				output.once('error', reject);
78			});
79			request.once('error', reject);
80		});
81	}
