1	// Generic legacy-corpus candidate ingest machinery.
2	//
3	// One admitted legacy application is described by a LegacyCandidateConfig; every stage below is a
4	// pure function of that configuration plus injected bytes, so the acquisition shape, the archive to
5	// git-tree reconciliation, the dependency closure, and the baseline install/build record can all be
6	// exercised offline. Only the default transport, extractor, and step runner touch the host, and the
7	// acquisition entry point refuses to run without exact purpose-bound consent.
8	import { execFileSync, spawnSync } from 'node:child_process';
9	import { createHash } from 'node:crypto';
10	import { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
11	import { request } from 'node:https';
12	import { charIn, createRegExp } from 'magic-regexp';
13	import { join, relative, resolve } from 'pathe';
14	import { joinURL, parseURL, withQuery } from 'ufo';
15	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
16	
17	export const LEGACY_CORPUS_CONSENT = 'VL-LEGACY-CORPUS-2026-08-10' as const;
18	
19	export const lowerHex40 = createRegExp(
20		charIn('0123456789').from('a', 'f').times(40).at.lineStart().at.lineEnd(),
21	);
22	export const lowerHex64 = createRegExp(
23		charIn('0123456789').from('a', 'f').times(64).at.lineStart().at.lineEnd(),
24	);
25	
26	export type LegacyCandidateId = 'react-papercups-v1-0-0';
27	
28	export type LegacyAcquisitionCaps = Readonly<{
29		maximumAcceptedResponses: number;
30		maximumApiResponseBytes: number;
31		maximumArchiveBytes: number;
32		maximumAggregateWireBytes: number;
33		maximumAggregateDecodedBytes: number;
34		requiredArchiveStreams: number;
35	}>;
36	
37	export type LegacyCandidateConfig = Readonly<{
38		id: LegacyCandidateId;
39		consentId: typeof LEGACY_CORPUS_CONSENT;
40		owner: string;
41		repository: string;
42		tag: string;
43		frontendRoot: string;
44		lockFileName: string;
45		caps: LegacyAcquisitionCaps;
46		requiredRevisionWindow: Readonly<{ from: string; through: string }>;
47		legacyCell: Readonly<{
48			installCommand: readonly string[];
49			buildCommand: readonly string[];
50			buildOutputDirectory: string;
51		}>;
52	}>;
53	
54	const defaultCaps: LegacyAcquisitionCaps = {
55		maximumAcceptedResponses: 7,
56		maximumApiResponseBytes: 16_777_216,
57		maximumArchiveBytes: 134_217_728,
58		maximumAggregateWireBytes: 314_572_800,
59		maximumAggregateDecodedBytes: 314_572_800,
60		requiredArchiveStreams: 2,
61	};
62	
63	export const legacyCandidates: readonly LegacyCandidateConfig[] = [
64		{
65			id: 'react-papercups-v1-0-0',
66			consentId: LEGACY_CORPUS_CONSENT,
67			owner: 'papercups-io',
68			repository: 'papercups',
69			tag: 'v1.0.0',
70			frontendRoot: 'assets',
71			lockFileName: 'package-lock.json',
72			caps: defaultCaps,
73			requiredRevisionWindow: { from: '2018-01-01T00:00:00Z', through: '2023-08-10T00:00:00Z' },
74			legacyCell: {
75				installCommand: ['ci', '--ignore-scripts', '--no-audit', '--no-fund'],
76				buildCommand: ['run', 'build'],
77				buildOutputDirectory: 'build',
78			},
79		},
80	] as const;
81	
82	export function isLegacyCandidateId(id: string | undefined): id is LegacyCandidateId {
83		return legacyCandidates.some((candidate) => candidate.id === id);
84	}
85	
86	export function legacyCandidateConfig(id: string | undefined): LegacyCandidateConfig {
87		const candidate = legacyCandidates.find((entry) => entry.id === id);
88		if (!candidate) throw new Error(`Unknown legacy corpus candidate: ${String(id)}`);
89		return candidate;
90	}
91	
92	export const workspaceRoot = resolve(import.meta.dirname, '../../../..');
93	export const evidenceRootFor = (config: LegacyCandidateConfig): string =>
94		`evidence/ingests/${config.id}`;
95	export const cacheRootFor = (config: LegacyCandidateConfig): string =>
96		`.versionless/cache/${config.id}-source`;
97	export const workRootFor = (config: LegacyCandidateConfig): string =>
98		`.versionless/work/${config.id}/legacy`;
99	
100	const apiOrigin = 'https://api.github.com';
101	const archiveOrigin = 'https://codeload.github.com';
102	const acquisitionHosts: readonly string[] = ['api.github.com', 'codeload.github.com'];
103	
104	export const repositoryEndpoint = (config: LegacyCandidateConfig): string =>
105		joinURL(apiOrigin, 'repos', config.owner, config.repository);
106	export const tagRefEndpoint = (config: LegacyCandidateConfig): string =>
107		joinURL(repositoryEndpoint(config), 'git/ref/tags', config.tag);
108	export const tagObjectEndpoint = (config: LegacyCandidateConfig, sha: string): string =>
109		joinURL(repositoryEndpoint(config), 'git/tags', sha);
110	export const commitEndpoint = (config: LegacyCandidateConfig, sha: string): string =>
111		joinURL(repositoryEndpoint(config), 'git/commits', sha);
112	export const treeEndpoint = (config: LegacyCandidateConfig, sha: string): string =>
113		withQuery(joinURL(repositoryEndpoint(config), 'git/trees', sha), { recursive: '1' });
114	export const blobEndpoint = (config: LegacyCandidateConfig, sha: string): string =>
115		joinURL(repositoryEndpoint(config), 'git/blobs', sha);
116	export const archiveEndpoint = (config: LegacyCandidateConfig, commitSha: string): string =>
117		joinURL(archiveOrigin, config.owner, config.repository, 'tar.gz', commitSha);
118	
119	export function candidateAllowlist(config: LegacyCandidateConfig): readonly string[] {
120		return [
121			repositoryEndpoint(config),
122			tagRefEndpoint(config),
123			commitEndpoint(config, '<validated-commit-sha>'),
124			treeEndpoint(config, '<validated-tree-sha>'),
125			archiveEndpoint(config, '<validated-commit-sha>'),
126		];
127	}
128	
129	export function assertAllowedAcquisitionUrl(url: string, config: LegacyCandidateConfig): void {
130		const parsed = parseURL(url);
131		const repositoryPath = `/repos/${config.owner}/${config.repository}`;
132		const archivePath = `/${config.owner}/${config.repository}/tar.gz/`;
133		if (
134			parsed.protocol !== 'https:' ||
135			!acquisitionHosts.includes(parsed.host ?? '') ||
136			parsed.auth ||
137			parsed.hash ||
138			(parsed.host === 'api.github.com'
139				? !(
140						parsed.pathname === repositoryPath ||
141						parsed.pathname.startsWith(`${repositoryPath}/`)
142					)
143				: !parsed.pathname.startsWith(archivePath))
144		)
145			throw new Error(`Legacy acquisition URL is outside literal consent: ${url}`);
146	}
147	
148	export type LegacyAcquisitionAttempt = Readonly<{
149		schemaVersion: 'versionless.official-source-attempt.v1';
150		candidate: Readonly<{ repository: string; requestedTag: string }>;
151		consentId: string;
152		result: 'started';
153		network: Readonly<{
154			method: 'GET';
155			credentials: 'none';
156			requestEncoding: 'identity';
157			redirectsAllowed: false;
158			retriesAllowed: false;
159			alternateHostsAllowed: false;
160		}>;
161		allowlist: readonly string[];
162		caps: LegacyAcquisitionCaps;
163		requiredRevisionWindow: Readonly<{ from: string; through: string }>;
164		publication: Readonly<{
165			evidenceRoot: string;
166			cacheRoot: string;
167			transactional: true;
168			readinessCredit: false;
169		}>;
170		nonclaims: readonly string[];
171	}>;
172	
173	export function acquisitionAttempt(config: LegacyCandidateConfig): LegacyAcquisitionAttempt {
174		return {
175			schemaVersion: 'versionless.official-source-attempt.v1',
176			candidate: {
177				repository: `${config.owner}/${config.repository}`,
178				requestedTag: config.tag,
179			},
180			consentId: config.consentId,
181			result: 'started',
182			network: {
183				method: 'GET',
184				credentials: 'none',
185				requestEncoding: 'identity',
186				redirectsAllowed: false,
187				retriesAllowed: false,
188				alternateHostsAllowed: false,
189			},
190			allowlist: candidateAllowlist(config),
191			caps: config.caps,
192			requiredRevisionWindow: config.requiredRevisionWindow,
193			publication: {
194				evidenceRoot: evidenceRootFor(config),
195				cacheRoot: cacheRootFor(config),
196				transactional: true,
197				readinessCredit: false,
198			},
199			nonclaims: [
200				'Starting this transaction establishes no tag identity, license, source integrity, dependency closure, framework, build, browser behavior, migration feasibility, pilot status, or production readiness.',
201				'The resulting evidence is reproducibility evidence, not certification or legal approval.',
202			],
203		};
204	}
205	
206	export const documentBytes = (value: unknown): string => `${JSON.stringify(value, null, 2)}\n`;
207	
208	export function gitBlobId(bytes: Uint8Array): string {
209		const header = Buffer.from(`blob ${bytes.byteLength}\0`);
210		return createHash('sha1')
211			.update(Buffer.concat([header, Buffer.from(bytes)]))
212			.digest('hex');
213	}
214	
215	export type TreeRow = Readonly<{ path: string; mode: string; type: string; sha: string }>;
216	
217	export type TreeSummary = Readonly<{
218		treeEntries: number;
219		treeBlobs: number;
220		treeDirectories: number;
221		treeSymlinks: number;
222		treeGitlinks: number;
223	}>;
224	
225	export function summarizeTree(rows: readonly TreeRow[]): TreeSummary {
226		return {
227			treeEntries: rows.length,
228			treeBlobs: rows.filter((row) => row.type === 'blob').length,
229			treeDirectories: rows.filter((row) => row.type === 'tree').length,
230			treeSymlinks: rows.filter((row) => row.mode === '120000').length,
231			treeGitlinks: rows.filter((row) => row.type === 'commit').length,
232		};
233	}
234	
235	export function regularBlobIndex(rows: readonly TreeRow[]): Map<string, string> {
236		return new Map(
237			rows
238				.filter((row) => row.type === 'blob' && row.mode !== '120000')
239				.map((row) => [row.path, row.sha]),
240		);
241	}
242	
243	export type ExtractedFile = Readonly<{ path: string; bytes: Uint8Array }>;
244	
245	export type NormalizedManifest = Readonly<{ text: string; sha256: string }>;
246	
247	export function normalizedManifest(files: readonly ExtractedFile[]): NormalizedManifest {
248		const lines = files
249			.map((file) => `${file.path} ${sha256(Buffer.from(file.bytes))} ${file.bytes.byteLength}`)
250			.sort();
251		const text = `${lines.join('\n')}\n`;
252		return { text, sha256: sha256(Buffer.from(text, 'utf8')) };
253	}
254	
255	export type ArchiveParity = Readonly<{
256		singleRoot: string;
257		safeEntries: number;
258		regularFiles: number;
259		directories: number;
260		specialEntries: number;
261		gitBlobs: number;
262		missingFiles: number;
263		extraFiles: number;
264		mismatchedBlobs: number;
265		normalizedManifestSha256: string;
266	}>;
267	
268	export function reconcileArchiveWithTree(input: {
269		singleRoot: string;
270		rows: readonly TreeRow[];
271		files: readonly ExtractedFile[];
272		directories: number;
273		specialEntries: number;
274	}): ArchiveParity {
275		const blobs = regularBlobIndex(input.rows);
276		const seen = new Set<string>();
277		let mismatchedBlobs = 0;
278		let extraFiles = 0;
279		for (const file of input.files) {
280			const expected = blobs.get(file.path);
281			if (expected === undefined) extraFiles += 1;
282			else {
283				seen.add(file.path);
284				if (gitBlobId(file.bytes) !== expected) mismatchedBlobs += 1;
285			}
286		}
287		return {
288			singleRoot: input.singleRoot,
289			safeEntries: input.files.length + input.directories,
290			regularFiles: input.files.length,
291			directories: input.directories,
292			specialEntries: input.specialEntries,
293			gitBlobs: blobs.size,
294			missingFiles: blobs.size - seen.size,
295			extraFiles,
296			mismatchedBlobs,
297			normalizedManifestSha256: normalizedManifest(input.files).sha256,
298		};
299	}
300	
301	export const archiveMatchesGitTree = (parity: ArchiveParity): boolean =>
302		parity.mismatchedBlobs === 0 && parity.missingFiles === 0 && parity.extraFiles === 0;
303	
304	type LockNode = Readonly<{
305		version?: unknown;
306		resolved?: unknown;
307		integrity?: unknown;
308		dependencies?: unknown;
309		dev?: unknown;
310		optional?: unknown;
311		bundled?: unknown;
312	}>;
313	
314	export type LockPlacement = Readonly<{
315		name: string;
316		version: string;
317		path: string;
318		resolved: string | null;
319		integrity: string | null;
320		dev: boolean;
321		optional: boolean;
322		bundled: boolean;
323	}>;
324	
325	export function collectLockPlacements(lock: unknown): LockPlacement[] {
326		const placements: LockPlacement[] = [];
327		const walk = (dependencies: unknown, parents: readonly string[]): void => {
328			if (dependencies === undefined || dependencies === null) return;
329			if (typeof dependencies !== 'object' || Array.isArray(dependencies))
330				throw new Error('Legacy lock dependencies must be an object');
331			for (const [name, value] of Object.entries(dependencies as Record<string, unknown>)) {
332				if (!value || typeof value !== 'object' || Array.isArray(value))
333					throw new Error(`Legacy lock node differs: ${[...parents, name].join('/')}`);
334				const node = value as LockNode;
335				if (typeof node.version !== 'string')
336					throw new Error(`Legacy lock version differs: ${[...parents, name].join('/')}`);
337				placements.push({
338					name,
339					version: node.version,
340					path: [...parents, name].join('/'),
341					resolved: typeof node.resolved === 'string' ? node.resolved : null,
342					integrity: typeof node.integrity === 'string' ? node.integrity : null,
343					dev: node.dev === true,
344					optional: node.optional === true,
345					bundled: node.bundled === true,
346				});
347				walk(node.dependencies, [...parents, name]);
348			}
349		};
350		if (!lock || typeof lock !== 'object' || Array.isArray(lock))
351			throw new Error('Legacy lock document must be an object');
352		walk((lock as { dependencies?: unknown }).dependencies, []);
353		return placements;
354	}
