361			verifiedSourceRoot: string;
362			packageJsonSha256: string;
363			packageLockSha256: string;
364			packageLockBytes: number;
365		}>;
366		lockState: Readonly<{
367			file: string;
368			lockfileVersion: number | null;
369			requiresField: boolean | null;
370			committedWithSource: true;
371			coversDevDependencies: boolean;
372			everyEntryHasResolvedUrl: boolean;
373			everyEntryHasIntegrityHash: boolean;
374			entriesWithoutResolvedUrl: readonly string[];
375			entriesWithoutIntegrityHash: readonly string[];
376			lockfileIntegrityAlgorithms: readonly string[];
377		}>;
378		counts: Readonly<{
379			declaredDependencies: number;
380			declaredDevDependencies: number;
381			lockedPlacements: number;
382			distinctNameVersionPairs: number;
383			devPlacements: number;
