392	export function analyzeLegacyLockClosure(
393		config: LegacyCandidateConfig,
394		input: {
395			verifiedSourceRoot: string;
396			packageBytes: Uint8Array;
397			lockBytes: Uint8Array;
398		},
399	): LegacyClosureRecord {
400		const manifest = JSON.parse(Buffer.from(input.packageBytes).toString('utf8')) as {
401			dependencies?: Record<string, unknown>;
402			devDependencies?: Record<string, unknown>;
403		};
404		const lock = JSON.parse(Buffer.from(input.lockBytes).toString('utf8')) as {
405			lockfileVersion?: unknown;
406			requires?: unknown;
407		};
408		const placements = collectLockPlacements(lock);
409		const hosts = new Map<string, number>();
410		for (const placement of placements) {
411			if (placement.resolved === null) continue;
412			const host = parseURL(placement.resolved).host ?? '';
413			hosts.set(host, (hosts.get(host) ?? 0) + 1);
414		}
415		const withoutResolved = placements.filter(
416			(placement) => placement.resolved === null && !placement.bundled,
417		);
418		const withoutIntegrity = placements.filter(
419			(placement) => placement.integrity === null && !placement.bundled,
420		);
421		const closureLines = placements
422			.map(
423				(placement) =>
424					`${placement.path} ${placement.version} ${placement.integrity ?? 'none'}`,
425			)
426			.sort();
427		return {
428			schemaVersion: 'versionless.legacy-dependency-closure.v1',
429			slug: config.id,
430			frontendRoot: config.frontendRoot,
431			source: {
432				verifiedSourceRoot: input.verifiedSourceRoot,
433				packageJsonSha256: sha256(Buffer.from(input.packageBytes)),
434				packageLockSha256: sha256(Buffer.from(input.lockBytes)),
435				packageLockBytes: input.lockBytes.byteLength,
436			},
437			lockState: {
438				file: config.lockFileName,
439				lockfileVersion: typeof lock.lockfileVersion === 'number' ? lock.lockfileVersion : null,
440				requiresField: typeof lock.requires === 'boolean' ? lock.requires : null,
441				committedWithSource: true,
442				coversDevDependencies: placements.some((placement) => placement.dev),
443				everyEntryHasResolvedUrl: withoutResolved.length === 0,
444				everyEntryHasIntegrityHash: withoutIntegrity.length === 0,
445				entriesWithoutResolvedUrl: withoutResolved.map((placement) => placement.path),
446				entriesWithoutIntegrityHash: withoutIntegrity.map((placement) => placement.path),
447				lockfileIntegrityAlgorithms: [
448					...new Set(
449						placements.map(
450							(placement) => (placement.integrity ?? 'none').split('-')[0] ?? 'none',
451						),
452					),
453				].sort(),
454			},
455			counts: {
456				declaredDependencies: Object.keys(manifest.dependencies ?? {}).length,
457				declaredDevDependencies: Object.keys(manifest.devDependencies ?? {}).length,
458				lockedPlacements: placements.length,
459				distinctNameVersionPairs: new Set(
460					placements.map((placement) => `${placement.name}@${placement.version}`),
461				).size,
462				devPlacements: placements.filter((placement) => placement.dev).length,
463				optionalPlacements: placements.filter((placement) => placement.optional).length,
464				bundledPlacements: placements.filter((placement) => placement.bundled).length,
465			},
466			registryHosts: Object.fromEntries(
467				[...hosts].sort(([left], [right]) => compare(left, right)),
468			),
469			closureSha256: sha256(Buffer.from(`${closureLines.join('\n')}\n`, 'utf8')),
470			nonclaims: [
471				'Per-artifact byte digests were not independently mirrored in this unit; the recorded integrity hashes are the ones the committed lockfile declares.',
472				'A resolvable closure establishes no build, browser behavior, licence compatibility of transitive dependencies, migration feasibility, or production readiness.',
473			],
474		};
475	}
