556	// A build step only runs when the install step succeeded: a failing install is recorded, not repaired.
557	export function runLegacyBaselineSteps(
558		config: LegacyCandidateConfig,
559		runner: LegacyStepRunner,
560		clock: LegacyClock = systemClock(),
561	): LegacyBaselineStep[] {
562		const steps: LegacyBaselineStep[] = [];
563		const execute = (name: string, args: readonly string[]): LegacyBaselineStep => {
564			const startedAt = clock.now().toISOString();
565			const started = clock.elapsedMs();
566			const outcome = runner(args);
567			return recordLegacyStep({
568				name,
569				args,
570				startedAt,
571				durationMs: clock.elapsedMs() - started,
572				outcome,
573			});
574		};
575		const install = execute('install', config.legacyCell.installCommand);
576		steps.push(install);
577		if (install.exitCode === 0) steps.push(execute('build', config.legacyCell.buildCommand));
578		return steps;
579	}
