637	export type LegacyAcquisitionState = {
638		requests: LegacyAcquiredResponse[];
639		aggregateBytes: number;
640		redirectsObserved: number;
641		setCookiesUsed: number;
642	};
643	
644	export type LegacyTransport = (
645		url: string,
646		kind: 'json' | 'archive',
647		state: LegacyAcquisitionState,
648		stream?: number,
649	) => Promise<Buffer>;
650	
651	export function newAcquisitionState(): LegacyAcquisitionState {
652		return { requests: [], aggregateBytes: 0, redirectsObserved: 0, setCookiesUsed: 0 };
653	}
654	
655	export function httpsTransport(config: LegacyCandidateConfig): LegacyTransport {
656		return (url, kind, state, stream) =>
657			new Promise<Buffer>((resolvePromise, reject) => {
658				assertAllowedAcquisitionUrl(url, config);
659				const cap =
660					kind === 'json'
661						? config.caps.maximumApiResponseBytes
662						: config.caps.maximumArchiveBytes;
663				const call = request(
664					url,
665					{
666						method: 'GET',
667						headers: {
668							accept:
669								kind === 'json'
670									? 'application/vnd.github+json'
671									: 'application/octet-stream',
672							'accept-encoding': 'identity',
673							'user-agent': 'versionless-shared-acquisition',
674							'x-versionless-consent-id': config.consentId,
675						},
676					},
677					(response) => {
678						const status = response.statusCode ?? 0;
679						if (status >= 300 && status < 400) state.redirectsObserved += 1;
680						if (response.headers['set-cookie']) state.setCookiesUsed += 1;
681						if (status !== 200) {
682							response.resume();
683							reject(new Error(`Legacy acquisition status differs: ${status} ${url}`));
684							return;
685						}
686						if ((response.headers['content-encoding'] ?? 'identity') !== 'identity') {
687							response.resume();
688							reject(new Error(`Legacy acquisition content encoding differs: ${url}`));
689							return;
690						}
691						const chunks: Buffer[] = [];
692						let bytes = 0;
693						response.on('data', (chunk: Buffer) => {
694							bytes += chunk.byteLength;
695							if (
696								bytes > cap ||
697								state.aggregateBytes + bytes > config.caps.maximumAggregateWireBytes
698							)
699								response.destroy(new Error(`Legacy acquisition cap exceeded: ${url}`));
700							else chunks.push(Buffer.from(chunk));
701						});
702						response.once('error', reject);
703						response.once('end', () => {
704							const body = Buffer.concat(chunks, bytes);
705							state.aggregateBytes += bytes;
706							state.requests.push({
707								endpoint: url,
708								status: 200,
709								bytes,
710								sha256: sha256(body),
711								...(stream === undefined ? {} : { stream }),
712							});
713							if (state.requests.length > config.caps.maximumAcceptedResponses) {
714								reject(new Error('Legacy acquisition accepted-response cap exceeded'));
715								return;
716							}
717							resolvePromise(body);
718						});
719					},
720				);
721				call.setTimeout(120_000, () =>
722					call.destroy(new Error(`Legacy acquisition timeout: ${url}`)),
723				);
724				call.once('error', reject);
725				call.end();
726			});
727	}
