804	async function walkExtracted(
805		directory: string,
806		base: string,
807	): Promise<{ files: ExtractedFile[]; directories: number; specialEntries: number }> {
808		const files: ExtractedFile[] = [];
809		let directories = 0;
810		let specialEntries = 0;
811		for (const entry of await readdir(directory, { withFileTypes: true })) {
812			const full = join(directory, entry.name);
813			if (entry.isDirectory()) {
814				directories += 1;
815				const nested = await walkExtracted(full, base);
816				files.push(...nested.files);
817				directories += nested.directories;
818				specialEntries += nested.specialEntries;
819			} else if (entry.isFile())
820				files.push({ path: relative(base, full), bytes: await readFile(full) });
821			else specialEntries += 1;
822		}
823		return { files, directories, specialEntries };
824	}
