826	// Acquires one candidate's official source under exact purpose-bound consent and publishes the
827	// attempt and source documents. Every remote byte flows through the injected transport, so the
828	// composition above stays testable without a network.
829	export async function acquireLegacyCandidateSource(
830		config: LegacyCandidateConfig,
831		options: {
832			allowNetwork: boolean;
833			consentId?: string;
834			transport?: LegacyTransport;
835			extract?: LegacyExtractor;
836			root?: string;
837		},
838	): Promise<{
839		manifest: { id: LegacyCandidateId };
840		consent: { consentId: string };
841		source: LegacySourceRecord;
842	}> {
843		assertLegacyAcquisitionConsent(config, options);
844		const root = options.root ?? workspaceRoot;
845		const transport = options.transport ?? httpsTransport(config);
846		const extract = options.extract ?? tarExtractor;
847		const evidenceDirectory = join(root, evidenceRootFor(config));
848		const cacheDirectory = join(root, cacheRootFor(config));
849		const archiveDirectory = join(cacheDirectory, 'archive');
850		const extractDirectory = join(cacheDirectory, 'verify/extracted');
851		await mkdir(archiveDirectory, { recursive: true });
852		await mkdir(evidenceDirectory, { recursive: true });
853	
854		const state = newAcquisitionState();
855		const startedAt = new Date().toISOString();
856		const readJson = async (url: string): Promise<Record<string, unknown>> =>
857			JSON.parse((await transport(url, 'json', state)).toString('utf8')) as Record<
858				string,
859				unknown
860			>;
861		const repository = await readJson(repositoryEndpoint(config));
862		const reference = await readJson(tagRefEndpoint(config));
863		const referenceObject = reference.object as { sha: string; type: string };
864		let tagObject: Record<string, unknown> | undefined;
865		let commitSha = referenceObject.sha;
866		if (referenceObject.type === 'tag') {
867			tagObject = await readJson(tagObjectEndpoint(config, referenceObject.sha));
868			commitSha = (tagObject.object as { sha: string }).sha;
869		}
870		const commit = await readJson(commitEndpoint(config, commitSha));
871		const rootTreeSha = (commit.tree as { sha: string }).sha;
872		const tree = await readJson(treeEndpoint(config, rootTreeSha));
873		if (tree.truncated === true)
874			throw new Error('Legacy git tree is truncated; refusing partial reconciliation');
875		const rows = tree.tree as TreeRow[];
876	
877		const archives: { file: string; sha256: string; bytes: number }[] = [];
878		for (let stream = 1; stream <= config.caps.requiredArchiveStreams; stream += 1) {
879			const body = await transport(archiveEndpoint(config, commitSha), 'archive', state, stream);
880			const file = join(archiveDirectory, `archive-${stream}.tar.gz`);
881			await writeFile(file, body);
882			archives.push({ file, sha256: sha256(body), bytes: body.byteLength });
883		}
884		const archivesByteIdentical = archives.every(
885			(archive) => archive.sha256 === (archives[0]?.sha256 ?? ''),
886		);
887		if (!archivesByteIdentical)
888			throw new Error('Legacy archive streams differ; refusing to publish source');
889	
890		await rm(extractDirectory, { recursive: true, force: true });
891		await mkdir(extractDirectory, { recursive: true });
892		extract(archives[0]?.file ?? '', extractDirectory);
893		const roots = await readdir(extractDirectory);
894		const singleRoot = roots[0];
895		if (roots.length !== 1 || singleRoot === undefined)
896			throw new Error(`Legacy archive has ${roots.length} roots`);
897		const sourceRoot = join(extractDirectory, singleRoot);
898		const walked = await walkExtracted(sourceRoot, sourceRoot);
899		const parity = reconcileArchiveWithTree({
900			singleRoot,
901			rows,
902			files: walked.files,
903			directories: walked.directories + 1,
904			specialEntries: walked.specialEntries,
905		});
906		await writeFile(join(cacheDirectory, 'manifest.txt'), normalizedManifest(walked.files).text);
907	
908		const attempt = acquisitionAttempt(config);
909		const attemptBytes = Buffer.from(documentBytes(attempt), 'utf8');
910		await writeFile(join(evidenceDirectory, 'attempt.json'), attemptBytes);
911		const first = state.requests[0];
912		if (!first) throw new Error('Legacy acquisition recorded no accepted responses');
913		const verification = (value: unknown): 'verified' | 'unsigned' =>
914			(value as { verified?: boolean } | undefined)?.verified === true ? 'verified' : 'unsigned';
915		const source: LegacySourceRecord = {
916			schemaVersion: 'versionless.official-source.v1',
917			consentId: config.consentId,
918			attemptSha256: sha256(attemptBytes),
919			result: 'source-bound',
920			startedAt,
921			completedAt: new Date().toISOString(),
922			repository: {
923				id: repository.id as number,
924				fullName: repository.full_name as string,
925				private: repository.private === true,
926				archived: repository.archived === true,
927				disabled: repository.disabled === true,
928				responseBytes: first.bytes,
929				responseSha256: first.sha256,
930			},
931			revision: {
932				ref: `refs/tags/${config.tag}`,
933				tagObjectSha: (tagObject?.sha as string | undefined) ?? null,
934				tagKind: tagObject ? 'annotated' : 'lightweight',
935				tagDate: ((tagObject?.tagger as { date?: string } | undefined)?.date ?? null) as
936					| string
937					| null,
938				tagVerification: verification(tagObject?.verification),
939				commitSha,
940				commitDate: ((commit.committer as { date?: string } | undefined)?.date ?? null) as
941					| string
942					| null,
943				commitVerification: verification(commit.verification),
944				rootTreeSha,
945				...summarizeTree(rows),
946				treeTruncated: tree.truncated === true,
947			},
948			requests: state.requests,
949			archiveParity: parity,
950			transaction: {
951				attemptedRequests: state.requests.length,
952				acceptedResponses: state.requests.length,
953				acceptedWireBytes: state.aggregateBytes,
954				acceptedDecodedBytes: state.aggregateBytes,
955				redirectsObserved: state.redirectsObserved,
956				setCookiesUsed: state.setCookiesUsed,
957				retries: 0,
958				archivesByteIdentical,
959				archiveMatchesGitTree: archiveMatchesGitTree(parity),
960				publishedSource: true,
961				readinessCredit: false,
