1	/**
2	 * The refusal census: every refusal this repository can emit from the code the
3	 * migration pipeline is made of, with its exact string, the condition that
4	 * raises it, and whose decision it is.
5	 *
6	 * The census is derived, not written. Each entry is read out of the source by
7	 * parsing it — the message from the thrown expression, the condition from the
8	 * guard the throw sits under, the location from the node — so a refusal cannot
9	 * be added, reworded or deleted in source without the census moving with it.
10	 * A hand-maintained list would be wrong within a week and would be wrong
11	 * silently, which is the failure mode this document exists to prevent.
12	 *
13	 * Two scopes are deliberate.
14	 *
15	 * The pipeline's own refusals are the `refuse()` call sites in
16	 * `packages/cli/src/operator/**`; those carry their own code, stage and origin,
17	 * and the census reads them rather than inventing any. A plain `throw` left in
18	 * those files is recorded as a **defect**, not as a refusal — that distinction
19	 * is the whole reason the exit codes differ.
20	 *
21	 * The frozen subtrees are enumerated read-only. T001 enumerated the 21 throws
22	 * in the operator flows and said so explicitly; the adapters were never
23	 * counted. They are counted here. Nothing in this module writes into a frozen
24	 * path, and the census records the freeze composite it was read at so a later
25	 * reader can tell whether it is still current.
26	 */
27	
28	import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
29	import * as path from 'pathe';
30	import { analyze } from 'yuku-analyzer';
31	import { ADAPTER_FREEZE_COMPOSITE } from '../../../trust/src/freeze.ts';
32	import type { RefusalOrigin } from './refusals.ts';
33	
34	export const REFUSAL_CENSUS_SCHEMA = 'versionless.refusal-census.v1';
35	
36	/** Where the census is published. */
37	export const REFUSAL_CENSUS_FILE = 'evidence/runs/operator-flows/refusal-census.json';
38	
39	/**
40	 * The modules the census reads, with the stage reading each one carries.
41	 *
42	 * The stage is a *static* reading: which operator stage composes this module,
43	 * with the basis for saying so. It is not a claim that every throw inside the
44	 * module is reachable from that stage — reachability per site was not computed,
45	 * and the census says as much rather than implying a call graph nobody ran.
46	 */
47	export type CensusModule = Readonly<{
48		/** Repo-relative path. */
49		file: string;
50		origin: RefusalOrigin;
51		/** `plan`, `build`, `plan-or-build`, `not-reached`, or an operator stage. */
52		stage: string;
53		stageBasis: string;
54	}>;
55	
56	const OPERATOR_MODULE = (file: string, stage: string, basis: string): CensusModule =>
57		Object.freeze({
58			file: `packages/cli/src/operator/${file}`,
59			origin: 'pipeline' as const,
60			stage,
61			stageBasis: basis,
62		});
63	
64	const REACT = 'packages/frameworks/react/src';
65	const ANGULAR = 'packages/frameworks/angular/src';
66	
67	const FROZEN_MODULE = (file: string, stage: string, basis: string): CensusModule =>
68		Object.freeze({ file, origin: 'frozen-adapter' as const, stage, stageBasis: basis });
69	
70	const ERA_MIGRATION_CHAIN =
71		'imported by angular-cli-era-migration.ts, which is the entry point planApplication composes for the Angular lineage.';
72	
73	const ERA_MIGRATION_TRANSITIVE =
74		'imported by capability modules that angular-cli-era-migration.ts composes, which is the entry point planApplication composes for the Angular lineage.';
75	
76	const NOT_COMPOSED_BY_ANY_STAGE =
77		'exported from the package barrel but composed by no operator stage: the flows compose craEntryDocument, planViteOriginConfigSource and migrateAngularCliEraWorkspace, and none of them reaches this module.';
78	
79	export const CENSUS_MODULES: readonly CensusModule[] = Object.freeze([
80		OPERATOR_MODULE(
81			'analyze.ts',
82			'analyze',
83			'the analyze stage reads the tree through this module.',
84		),
85		OPERATOR_MODULE('apply.ts', 'apply', 'the apply stage writes the lane through this module.'),
86		OPERATOR_MODULE(
87			'build.ts',
88			'build',
89			'the build stage runs the lane build through this module.',
90		),
91		OPERATOR_MODULE(
92			'flows.ts',
93			'arguments',
94			'the command surface parses and validates arguments here before any stage runs.',
95		),
96		OPERATOR_MODULE(
97			'install.ts',
98			'install',
99			'the install stage resolves the lane closure through this module.',
100		),
101		OPERATOR_MODULE(
102			'lane.ts',
103			'lane',
104			'the lane stage composes the generated build configuration and the manifest rewrite here.',
