282	type Node = Record<string, unknown> & { type: string; start: number; end: number };
283	
284	function isNode(value: unknown): value is Node {
285		return (
286			value !== null &&
287			typeof value === 'object' &&
288			typeof (value as { type?: unknown }).type === 'string'
289		);
290	}
