292	/** Collapse every whitespace run to one space, so a guard reads on one line. */
293	export function collapseWhitespace(value: string): string {
294		const parts: string[] = [];
295		let current = '';
296		for (const character of value) {
297			const white =
298				character === ' ' ||
299				character === '\t' ||
300				character === '\n' ||
301				character === '\r' ||
302				character === '\f' ||
303				character === '\v';
304			if (white) {
305				if (current !== '') parts.push(current);
306				current = '';
307				continue;
308			}
309			current += character;
310		}
311		if (current !== '') parts.push(current);
312		return parts.join(' ');
313	}
314	
315	type Segment = Readonly<{ kind: 'text' | 'expression'; value: string }>;
316	
317	function messageSegments(node: Node | undefined, source: string): Segment[] {
318		if (node === undefined) return [];
319		if (node.type === 'Literal' && typeof node.value === 'string')
320			return [{ kind: 'text', value: node.value }];
321		if (node.type === 'TemplateLiteral') {
322			const quasis = (node.quasis ?? []) as Node[];
323			const expressions = (node.expressions ?? []) as Node[];
324			const segments: Segment[] = [];
325			for (let index = 0; index < quasis.length; index += 1) {
326				const quasi = quasis[index] as Node | undefined;
327				const cooked = (quasi?.value as { cooked?: string } | undefined)?.cooked ?? '';
328				if (cooked !== '') segments.push({ kind: 'text', value: cooked });
329				const expression = expressions[index];
330				if (expression !== undefined)
331					segments.push({
332						kind: 'expression',
333						value: collapseWhitespace(source.slice(expression.start, expression.end)),
334					});
335			}
336			return segments;
337		}
338		if (node.type === 'BinaryExpression' && node.operator === '+')
339			return [
340				...messageSegments(node.left as Node | undefined, source),
341				...messageSegments(node.right as Node | undefined, source),
342			];
343		return [{ kind: 'expression', value: collapseWhitespace(source.slice(node.start, node.end)) }];
344	}
345	
346	function renderSegments(segments: readonly Segment[]): string {
347		return segments
348			.map((segment) => (segment.kind === 'text' ? segment.value : `\${${segment.value}}`))
349			.join('');
350	}
351	
352	function lineOf(source: string, offset: number): number {
353		let line = 1;
354		for (let index = 0; index < offset && index < source.length; index += 1)
355			if (source[index] === '\n') line += 1;
356		return line;
357	}
358	
359	const FUNCTION_TYPES: readonly string[] = Object.freeze([
360		'FunctionDeclaration',
361		'FunctionExpression',
362		'ArrowFunctionExpression',
363	]);
364	
365	function enclosingName(ancestors: readonly Node[]): string {
366		for (let index = ancestors.length - 1; index >= 0; index -= 1) {
367			const node = ancestors[index] as Node;
368			if (node.type === 'FunctionDeclaration') {
369				const id = node.id as Node | undefined;
370				const name = id === undefined ? null : (id.name as string | undefined);
371				if (name !== undefined && name !== null) return name;
372			}
373			if (node.type === 'VariableDeclarator') {
374				const id = node.id as Node | undefined;
375				const name = id === undefined ? null : (id.name as string | undefined);
376				if (name !== undefined && name !== null) return name;
377			}
378			if (node.type === 'MethodDefinition' || node.type === 'Property') {
379				const key = node.key as Node | undefined;
380				const name = key === undefined ? null : (key.name as string | undefined);
381				if (name !== undefined && name !== null) return name;
382			}
383		}
384		return 'module scope';
385	}
386	
387	function guardOf(
388		ancestors: readonly Node[],
389		site: Node,
390		source: string,
391	): { condition: string; conditionForm: CensusEntry['conditionForm'] } {
392		for (let index = ancestors.length - 1; index >= 0; index -= 1) {
393			const node = ancestors[index] as Node;
394			if (FUNCTION_TYPES.includes(node.type)) break;
395			if (node.type !== 'IfStatement') continue;
396			const test = node.test as Node;
397			const consequent = node.consequent as Node | undefined;
398			const inConsequent =
399				consequent !== undefined &&
400				site.start >= consequent.start &&
401				site.end <= consequent.end;
402			return {
403				condition: collapseWhitespace(source.slice(test.start, test.end)),
404				conditionForm: inConsequent ? 'if-consequent' : 'if-alternate',
405			};
406		}
407		return {
408			condition: `unconditional within ${enclosingName(ancestors)}`,
409			conditionForm: 'unconditional',
410		};
411	}
