413	const SLUG_LIMIT = 64;
414	
415	/** A stable, readable identifier derived from the site's own first words. */
416	export function slugOf(value: string): string {
417		let slug = '';
418		let pendingSeparator = false;
419		for (const character of value.toLowerCase()) {
420			const code = character.charCodeAt(0);
421			const alphanumeric = (code >= 97 && code <= 122) || (code >= 48 && code <= 57);
422			if (!alphanumeric) {
423				pendingSeparator = slug !== '';
424				continue;
425			}
426			if (pendingSeparator) {
427				if (slug.length >= SLUG_LIMIT) break;
428				slug += '-';
429				pendingSeparator = false;
430			}
431			if (slug.length >= SLUG_LIMIT) break;
432			slug += character;
433		}
434		return slug === '' ? 'unnamed' : slug;
435	}
