445	async function typeScriptFilesBelow(directory: string): Promise<string[]> {
446		const files: string[] = [];
447		const entries = await readEntries(directory);
448		for (const entry of entries.sort((left, right) => (left.name < right.name ? -1 : 1))) {
449			if (
450				entry.name === 'node_modules' ||
451				entry.name === '.git' ||
452				entry.name === 'dist' ||
453				entry.name === 'test'
454			)
455				continue;
456			const item = path.join(directory, entry.name);
457			if (entry.isDirectory()) {
458				files.push(...(await typeScriptFilesBelow(item)));
459				continue;
460			}
461			if (entry.isFile() && path.extname(entry.name) === '.ts') files.push(item);
462		}
463		return files;
464	}
