466	type Site = Readonly<{
467		node: Node;
468		ancestors: readonly Node[];
469		kind: 'refuse-call' | 'throw-error';
470		argument: Node | undefined;
471		properties: Readonly<Record<string, Node>>;
472	}>;
473	
474	function propertiesOf(node: Node | undefined): Readonly<Record<string, Node>> {
475		if (node === undefined || node.type !== 'ObjectExpression') return {};
476		const record: Record<string, Node> = {};
477		for (const property of (node.properties ?? []) as Node[]) {
478			if (property.type !== 'Property') continue;
479			const key = property.key as Node | undefined;
480			const name = key === undefined ? undefined : (key.name as string | undefined);
481			const value = property.value as Node | undefined;
482			if (name !== undefined && value !== undefined) record[name] = value;
483		}
484		return record;
485	}
486	
487	type RecordedSite = Readonly<{ node: Node; callee: string; argument: Node | undefined }>;
488	
489	/**
490	 * Call sites named `refuse` or `refused` inside a frozen subtree.
491	 *
492	 * These are refusals the adapters *record* rather than throw — a local helper
493	 * appends a reason to a per-file refusal list, and the caller decides what to
494	 * do with it. They do not carry the pipeline's `{ code, message, stage, origin }`
495	 * shape, so the census does not pretend to have read one. What it does is count
496	 * and locate them, so the gap is a number instead of an absence.
497	 */
498	const RECORDED_REFUSAL_CALLEES: readonly string[] = Object.freeze(['refuse', 'refused']);
499	
500	function collectSites(
501		root: Node,
502		structured: boolean,
503	): { sites: Site[]; recorded: RecordedSite[] } {
504		const sites: Site[] = [];
505		const recorded: RecordedSite[] = [];
506		const walk = (node: Node, ancestors: Node[]): void => {
507			if (node.type === 'ThrowStatement') {
508				const argument = node.argument as Node | undefined;
509				const callee =
510					argument === undefined ? undefined : (argument.callee as Node | undefined);
511				if (
512					argument?.type === 'NewExpression' &&
513					callee?.type === 'Identifier' &&
514					callee.name === 'Error'
515				)
516					sites.push({
517						node,
518						ancestors: [...ancestors],
519						kind: 'throw-error',
520						argument: ((argument.arguments ?? []) as Node[])[0],
521						properties: {},
522					});
523			}
524			if (node.type === 'CallExpression') {
525				const callee = node.callee as Node | undefined;
526				const name = callee?.type === 'Identifier' ? (callee.name as string) : null;
527				if (name !== null && RECORDED_REFUSAL_CALLEES.includes(name)) {
528					const args = (node.arguments ?? []) as Node[];
529					if (structured && name === 'refuse')
530						sites.push({
531							node,
532							ancestors: [...ancestors],
533							kind: 'refuse-call',
534							argument: args[0],
535							properties: propertiesOf(args[0]),
536						});
537					else recorded.push({ node, callee: name, argument: args[args.length - 1] });
538				}
539			}
540			ancestors.push(node);
541			for (const key of Object.keys(node)) {
542				if (key === 'type' || key === 'start' || key === 'end') continue;
543				const value = node[key];
544				if (Array.isArray(value)) {
545					for (const item of value) if (isNode(item)) walk(item, ancestors);
546					continue;
547				}
548				if (isNode(value)) walk(value, ancestors);
549			}
550			ancestors.pop();
551		};
552		walk(root, []);
553		return { sites, recorded };
554	}
555	
556	function staticStringOf(node: Node | undefined, source: string): string | null {
557		const segments = messageSegments(node, source);
558		if (segments.length === 0) return null;
559		return segments.every((segment) => segment.kind === 'text') ? renderSegments(segments) : null;
560	}
561	
562	const compareEntries = (left: CensusEntry, right: CensusEntry): number => {
563		if (left.file !== right.file) return left.file < right.file ? -1 : 1;
564		return left.line - right.line;
565	};
