567	/** Derive the census from the checkout. Frozen paths are read, never written. */
568	export async function buildRefusalCensus(rootDir = '.'): Promise<RefusalCensus> {
569		const root = path.resolve(rootDir);
570		const modules = new Map(CENSUS_MODULES.map((module) => [module.file, module]));
571		const entries: CensusEntry[] = [];
572		const recordedRefusals: RecordedRefusal[] = [];
573		const usedCodes = new Map<string, number>();
574		let filesScanned = 0;
575		const unlisted: string[] = [];
576		for (const scanned of CENSUS_ROOTS) {
577			const scanRoot = path.join(root, scanned.root);
578			for (const file of await typeScriptFilesBelow(scanRoot)) {
579				const relative = path.relative(root, file);
580				const source = await readFile(file, 'utf8');
581				filesScanned += 1;
582				const collected = collectSites(
583					analyze(source, { path: relative }).ast as unknown as Node,
584					scanned.origin === 'pipeline',
585				);
586				for (const site of collected.recorded) {
587					const segments = messageSegments(site.argument, source);
588					if (segments.length === 0) continue;
589					recordedRefusals.push(
590						Object.freeze({
591							callee: site.callee,
592							message: renderSegments(segments),
593							messageForm: segments.every((segment) => segment.kind === 'text')
594								? ('static' as const)
595								: ('composed' as const),
596							origin: scanned.origin,
597							file: relative,
598							line: lineOf(source, site.node.start),
599							enclosing: 'recorded through a local helper',
600						}),
601					);
602				}
603				const sites = collected.sites;
604				if (sites.length === 0) continue;
605				const module = modules.get(relative);
606				if (module === undefined) {
607					unlisted.push(relative);
608					continue;
609				}
610				for (const site of sites) {
611					const messageNode =
612						site.kind === 'refuse-call' ? site.properties.message : site.argument;
613					const segments = messageSegments(messageNode, source);
614					const message = renderSegments(segments);
615					const staticSegments = segments
616						.filter((segment) => segment.kind === 'text')
617						.map((segment) => segment.value.trim())
618						.filter((segment) => segment !== '');
619					const declaredCode =
620						site.kind === 'refuse-call'
621							? staticStringOf(site.properties.code, source)
622							: null;
623					const declaredStage =
624						site.kind === 'refuse-call'
625							? staticStringOf(site.properties.stage, source)
626							: null;
627					const declaredOrigin =
628						site.kind === 'refuse-call'
629							? staticStringOf(site.properties.origin, source)
630							: null;
631					const stem = path.basename(relative, '.ts');
632					const fallback = `${module.origin === 'pipeline' ? 'pipeline' : 'frozen'}.${stem}.${slugOf(staticSegments[0] ?? message)}`;
633					const baseCode = declaredCode ?? fallback;
634					const seen = usedCodes.get(baseCode) ?? 0;
635					usedCodes.set(baseCode, seen + 1);
636					const code = seen === 0 ? baseCode : `${baseCode}-${String(seen + 1)}`;
637					const classification: CensusEntry['classification'] =
638						site.kind === 'refuse-call'
639							? 'refusal'
640							: module.origin === 'pipeline'
641								? 'defect'
642								: (staticSegments[0] ?? '').startsWith('Refused:')
643									? 'refusal'
644									: 'unclassified';
645					const guard = guardOf(site.ancestors, site.node, source);
646					entries.push(
647						Object.freeze({
648							code,
649							message,
650							messageForm: segments.every((segment) => segment.kind === 'text')
651								? ('static' as const)
652								: ('composed' as const),
653							staticSegments: Object.freeze(staticSegments),
654							classification,
655							condition: guard.condition,
656							conditionForm: guard.conditionForm,
657							origin:
658								declaredOrigin === 'frozen-adapter' || declaredOrigin === 'pipeline'
659									? declaredOrigin
660									: module.origin,
661							stage: declaredStage ?? module.stage,
662							stageBasis: module.stageBasis,
663							file: relative,
664							line: lineOf(source, site.node.start),
665							enclosing: enclosingName(site.ancestors),
666						}),
667					);
668				}
669			}
670		}
671		if (unlisted.length > 0)
672			throw new Error(
673				`refusal-census: ${String(unlisted.length)} scanned file(s) raise refusals and are not declared in CENSUS_MODULES: ${unlisted.sort().join(', ')}. Declare the module and the basis for its stage reading rather than let the census drop the sites.`,
674			);
675		entries.sort(compareEntries);
676		recordedRefusals.sort((left, right) =>
677			left.file === right.file ? left.line - right.line : left.file < right.file ? -1 : 1,
678		);
679		const byOrigin: Record<string, number> = {};
680		const byClassification: Record<string, number> = {};
681		const byStage: Record<string, number> = {};
682		for (const entry of entries) {
683			byOrigin[entry.origin] = (byOrigin[entry.origin] ?? 0) + 1;
684			byClassification[entry.classification] = (byClassification[entry.classification] ?? 0) + 1;
685			byStage[entry.stage] = (byStage[entry.stage] ?? 0) + 1;
686		}
687		const sortedRecord = (record: Record<string, number>): Readonly<Record<string, number>> =>
688			Object.freeze(
689				Object.fromEntries(
690					Object.keys(record)
691						.sort((left, right) => (left < right ? -1 : 1))
692						.map((key) => [key, record[key] as number]),
693				),
694			);
695		return Object.freeze({
696			schemaVersion: REFUSAL_CENSUS_SCHEMA,
697			generatedBy: 'versionless refusal-census',
698			adapterFreezeComposite: ADAPTER_FREEZE_COMPOSITE,
699			roots: Object.freeze(CENSUS_ROOTS.map((scanned) => scanned.root)),
700			filesScanned,
701			summary: Object.freeze({
702				sites: entries.length,
703				byOrigin: sortedRecord(byOrigin),
704				byClassification: sortedRecord(byClassification),
705				byStage: sortedRecord(byStage),
706				distinctCodes: new Set(entries.map((entry) => entry.code)).size,
707				recordedRefusalSites: recordedRefusals.length,
708			}),
709			entries: Object.freeze(entries),
710			recordedRefusals: Object.freeze(recordedRefusals),
711			notEstablished: CENSUS_NOT_ESTABLISHED,
712		});
713	}
714	
715	/** Write the census where the trust surfaces and the fleet report can read it. */
716	export async function writeRefusalCensus(
717		census: RefusalCensus,
718		file = REFUSAL_CENSUS_FILE,
719	): Promise<string> {
720		const target = path.resolve(file);
721		await mkdir(path.dirname(target), { recursive: true });
722		await writeFile(target, `${JSON.stringify(census, null, '\t')}\n`);
723		return file;
724	}
