const fs=require('fs'),crypto=require('crypto'),path=require('path');
const prov=JSON.parse(fs.readFileSync('evidence/trust/current/provenance.json','utf8'));
const subs=prov.subject.map(s=>({path:s.name,sha256:s.digest.sha256})).sort((a,b)=>a.path<b.path?-1:1);
function walk(d,out=[]){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p,out);else out.push(p);}return out;}
const actual=walk('packages').filter(f=>f.includes('/dist/')).map(f=>({path:f,sha256:crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex')})).sort((a,b)=>a.path<b.path?-1:1);
console.log('provenance subjects',subs.length,'actual',actual.length);
for(const a of actual){const s=subs.find(x=>x.path===a.path);if(!s)console.log('EXTRA',a.path);else if(s.sha256!==a.sha256)console.log('DIFFER',a.path,'\n  prov',s.sha256,'\n  disk',a.sha256, 'mtime', fs.statSync(a.path).mtime.toISOString());}
for(const s of subs){if(!actual.find(x=>x.path===s.path))console.log('MISSING',s.path);}
